root=Path('/mnt/data/v22/work')

def js(s):
    return json.dumps(s, ensure_ascii=False)

tracks={
'Java / JVM':[
('Class loading','Class loading turns bytecode into a usable runtime type.','The JVM locates a class, loads its bytes, verifies and prepares it, then initializes it when required. Parent delegation prevents ordinary loaders from redefining core classes accidentally.','Class.forName("com.example.Payment");','I separate loading, linking and initialization; that distinction explains many NoClassDefFoundError and initialization failures.'),
('Stack vs heap','Each thread has its own stack frames while objects normally live in the heap.','A method call creates a frame containing locals and operand state; object allocation is managed by the JVM heap and collector. Escape analysis may optimize some allocations.','void pay(){ int amount=10; Payment p=new Payment(); }','I use stack and heap as a mental model, then qualify it: the JVM is free to optimize representation.'),
('JIT compilation','The JIT turns frequently executed bytecode into optimized native machine code at runtime.','The JVM profiles execution, identifies hot methods, compiles them and can apply inlining and other speculative optimizations.','for(int i=0;i<1_000_000;i++) total += calculate(i);','I explain why warm-up and workload shape can affect observed Java performance.'),
('Safepoints','A safepoint is a JVM coordination point where threads can reach a state safe for certain VM operations.','Threads move through poll points and the JVM waits for required threads before operations such as some GC phases or deoptimization.','-XX:+PrintGCDetails','I avoid saying every GC is a full stop-the-world event; I explain the collector and safepoint behavior involved.'),
('Java Memory Model','The Java Memory Model defines when writes by one thread become visible to another and what reorderings are legal.','Happens-before relationships arise from synchronization, volatile access, thread start/join and other rules.','volatile boolean ready;','I reason from happens-before rather than from source-code order alone.'),
('Thread pools','A thread pool bounds and reuses worker threads for submitted tasks.','Tasks enter a queue, workers execute them, and saturation depends on queue policy, worker count and task duration.','ExecutorService pool = Executors.newFixedThreadPool(8);','I size pools from workload characteristics and downstream capacity instead of choosing a number by habit.')],
'Spring Internals':[
('Bean definition to bean instance','A Spring bean begins as metadata describing how the container should create and configure an object.','Bean definitions are discovered, dependencies resolved, instances created and post-processors applied before the bean is exposed.','@Bean PaymentService paymentService(){ return new PaymentService(); }','I describe the container as a lifecycle pipeline, which makes startup and wiring problems easier to reason about.'),
('Dependency injection resolution','Dependency injection resolves a bean dependency from the application context rather than the class constructing it itself.','Spring considers type, qualifiers, primary candidates and injection metadata when selecting a dependency.','@Qualifier("stripe") PaymentGateway gateway;','I explain why constructor injection plus explicit qualifiers makes dependency selection predictable.'),
('Bean post-processors','BeanPostProcessors can inspect, modify or wrap beans during container creation.','Before/after initialization callbacks allow infrastructure such as AOP and annotation-driven features to participate in bean creation.','class AuditProcessor implements BeanPostProcessor { }','I use post-processors to explain why a bean may be proxied or behave differently after creation.'),
('Spring proxies','Spring proxies intercept calls to apply cross-cutting behavior such as transactions, caching or security.','JDK proxies implement interfaces; subclass-based proxies extend concrete classes. Calls must cross the proxy for advice to run.','proxy.payment(); // advice can run here','I always identify the proxy boundary before explaining why an annotation did or did not take effect.'),
('Application startup','Spring Boot startup builds the application context and prepares infrastructure before serving requests.','Configuration is discovered, auto-configuration is evaluated, beans are created and lifecycle callbacks run.','SpringApplication.run(App.class,args);','I troubleshoot startup by locating the first failing bean or configuration boundary, not the last stack-trace line.'),
('Auto-configuration conditions','Boot auto-configuration adds infrastructure when classpath, properties and existing beans satisfy conditions.','Conditional annotations decide whether a configuration contributes beans, allowing sensible defaults without overriding explicit application configuration.','@ConditionalOnClass(DataSource.class)','I explain auto-configuration as conditional defaults rather than hidden magic.')],
'Spring Web / Security':[
('Filter chain ordering','HTTP filters execute around the servlet request and their order determines which concerns run first.','Spring Security builds a filter chain that can authenticate, authorize, reject or continue the request before MVC controller invocation.','http.addFilterBefore(customFilter, UsernamePasswordAuthenticationFilter.class);','I diagnose security behavior by tracing the filter chain before looking at the controller.'),
('Handler mapping','Spring MVC maps an incoming request to a controller handler method.','DispatcherServlet asks HandlerMappings for a matching handler based on path, method and other conditions.','GET /orders/42 -> OrderController#get(42)','I use handler mapping to explain 404 versus 405 and why a request never reached business logic.'),
('Message conversion','Spring converts HTTP representations such as JSON into Java objects and back.','HttpMessageConverters inspect content type and use serializers such as Jackson for request and response bodies.','OrderRequest req // JSON -> object','I distinguish transport serialization from validation and business rules.'),
('JWT validation','JWT validation proves that a token is structurally and cryptographically acceptable before its claims are trusted.','The resource server validates signature, issuer, audience and time claims according to configuration, then creates an authenticated principal.','Authorization: Bearer eyJ...','I never treat decoding a JWT as validation; trust begins only after verification succeeds.'),
('Authentication vs authorization','Authentication establishes who the caller is; authorization decides what that caller may do.','Security filters can establish an authenticated principal, while authorization rules evaluate authorities against the requested resource.','@PreAuthorize("hasRole(\'ADMIN\')")','I explain the two decisions separately because a valid identity does not imply permission.'),
('Exception translation','Security and MVC translate internal failures into stable HTTP responses.','Authentication failures commonly become 401, access denial becomes 403, and controller errors can be centralized with exception handlers.','@RestControllerAdvice class Errors { }','I trace the boundary that owns the response instead of returning ad-hoc errors from every layer.')],
'JPA / Hibernate':[
('Persistence context','The persistence context is Hibernate’s managed identity scope for entities.','Within one context, a database row is represented by one managed entity instance; changes can be tracked until flush.','Order a = em.find(Order.class,1L); Order b = em.find(Order.class,1L);','I connect persistence context, identity map and dirty checking rather than treating JPA as a simple SQL wrapper.'),
('Entity state transitions','Entities move among transient, managed, detached and removed states.','persist attaches new state, detach/clear removes management, merge copies detached state into a managed instance, and remove schedules deletion.','em.persist(order); em.flush();','I choose the operation based on entity state instead of using merge blindly.'),
('Dirty checking','Dirty checking detects changes to managed entity state and synchronizes them during flush.','Hibernate keeps enough state to determine what changed and generates SQL for dirty managed entities.','order.setStatus("PAID"); // SQL later','I explain why a setter can cause an UPDATE without an explicit repository save.'),
('Flush vs commit','Flush synchronizes persistence context state with the database; commit completes the transaction.','A flush can happen before commit, including before queries under some modes, while commit finalizes the transaction.','entityManager.flush();','I never equate flush with commit; visibility and durability still depend on transaction semantics.'),
('Lazy loading','Lazy loading defers association retrieval until the association is accessed.','Hibernate can use proxies or enhanced state to issue a query when a lazy relationship is first needed.','order.getItems().size(); // may query','I make fetch strategy an explicit API and transaction-boundary decision rather than exposing lazy entities blindly.'),
('N+1 query mechanism','N+1 occurs when one query loads parent rows and repeated lazy access triggers one query per parent.','The first query returns N parents; iteration then initializes each association separately. Fetch joins, entity graphs or batch fetching can reduce round trips.','SELECT o FROM Order o JOIN FETCH o.items','I identify N+1 from query counts and request shape, then choose the smallest correct fetch strategy.')],
'SQL / PostgreSQL':[
('B-tree index lookup','A B-tree index keeps keys ordered so the engine can navigate to matching ranges efficiently.','The planner can use the index to find a narrow key range and then fetch table rows or perform an index-only strategy when possible.','CREATE INDEX idx_orders_customer ON orders(customer_id);','I explain an index as an access path with a cost, not as a magic speed switch.'),
('Query planning','The optimizer chooses an execution plan using statistics, predicates, indexes, joins and estimated costs.','EXPLAIN reveals scans, joins, row estimates and actual work when EXPLAIN ANALYZE is used.','EXPLAIN (ANALYZE, BUFFERS) SELECT ...;','I compare estimated versus actual rows first because bad cardinality estimates often lead to bad plans.'),
('MVCC','Multi-version concurrency control lets transactions work with consistent row versions while reducing reader/writer blocking.','PostgreSQL tracks row versions and transaction visibility so a query sees rows valid for its snapshot.','SELECT txid_current();','I explain MVCC through snapshots and row versions, then connect it to vacuum and bloat.'),
('Locking','Database locks coordinate conflicting operations so concurrent transactions preserve required invariants.','Row and table locks can block or conflict; transaction design determines how long locks are held and whether deadlocks can occur.','SELECT * FROM orders WHERE id=1 FOR UPDATE;','I diagnose lock waits by identifying the blocked statement and the transaction holding the conflicting lock.'),
('Isolation levels','Isolation controls which effects of concurrent transactions can be observed.','PostgreSQL implements isolation using snapshots and locking behavior; stronger isolation can improve guarantees while increasing aborts or contention.','SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;','I select isolation from the invariant that must hold, not from a blanket “highest is best” rule.'),
('Connection pooling','A pool reuses database connections so requests do not repeatedly pay connection setup cost.','Borrowers acquire a connection, execute work and return it; saturation occurs when all connections are busy or leaked.','HikariDataSource ds;','I tune pool size with database capacity and request concurrency, because a bigger pool can overload the database.')],
'Microservices':[
('Request path across services','A distributed request crosses process and network boundaries, so latency and failure can occur at every hop.','Service A calls B, B may call C or a database, and each hop adds timeout, serialization and resource costs.','A -> B -> C -> DB','I draw the request path first because it reveals where latency, retries and ownership actually live.'),
('Timeout propagation','A timeout limits how long a caller waits for a downstream operation.','Timeouts should be bounded across the call chain so a slow dependency does not consume every caller thread indefinitely.','client.timeout(800);','I set timeouts from an end-to-end latency budget and ensure downstream timeouts do not exceed the caller’s remaining budget.'),
('Retry amplification','Retries can multiply load when several layers retry the same failing dependency.','If each layer retries independently, one original request can create many downstream attempts and worsen an outage.','retry(3) * retry(3) = 9 attempts','I prefer one well-placed retry policy with backoff and jitter and only for operations that are safe to retry.'),
('Circuit breaker states','A circuit breaker stops repeatedly calling an unhealthy dependency after failures cross a threshold.','Closed permits traffic, open fails fast, and half-open probes recovery before restoring normal traffic.','breaker.execute(remoteCall);','I explain the breaker as a load-shedding mechanism, not a fix for the dependency itself.'),
('Distributed transaction boundary','A business operation spanning services cannot rely on one local database transaction.','Each service commits locally and coordination is achieved through patterns such as saga, outbox and compensating actions.','Order DB tx -> event -> Payment DB tx','I choose a distributed consistency pattern based on business invariants and acceptable temporary inconsistency.'),
('Idempotency at service boundary','Idempotency lets repeated requests produce one logical effect.','A stable idempotency key is stored with the operation result or state so duplicate attempts can be recognized safely.','POST /payments\nIdempotency-Key: 7f2...','I make the boundary idempotent before adding retries because retries are expected in distributed systems.')],
'Kafka':[
('Partition leadership','Each Kafka partition has a leader broker responsible for normal client reads and writes.','Followers replicate the partition log; leadership can move after broker failure so another replica serves the partition.','topic orders partition 3 -> leader broker-2','I explain availability and ordering at partition scope, not topic-wide.'),
('Consumer group coordination','A consumer group divides partitions among its consumers so work is distributed.','Membership changes trigger rebalancing, which changes partition ownership and can pause processing.','group: orders-consumers\npartitions: 0,1,2','I reason about scaling from partition count because consumers cannot parallelize a partition beyond its ordering model.'),
('Offsets','A consumer offset represents its position in a partition log.','Committing an offset records progress; the timing of processing versus commit determines at-least-once or possible loss behavior.','consumer.commitSync();','I tie offset commit to the side effect so recovery semantics are explicit.'),
('Delivery semantics','Kafka applications can provide at-most-once, at-least-once or carefully designed effectively-once behavior.','The broker alone does not make an external database side effect exactly once; application idempotency and transactions determine end-to-end behavior.','process(record); commitOffset();','I distinguish Kafka’s guarantees from the guarantees of the whole business workflow.'),
('Log compaction','Compaction retains the latest value for keys while allowing older records to be removed over time.','The broker rewrites segments and preserves the latest record per key, making compacted topics useful for state reconstruction.','cleanup.policy=compact','I use compaction for changelog/state topics, not as a substitute for arbitrary event retention.'),
('Consumer lag','Consumer lag measures how far a consumer group is behind the latest available records.','Lag grows when production rate exceeds consumption capacity or when consumers are blocked by downstream work.','records-lag-max','I correlate lag with processing latency, partition skew and dependency saturation before simply adding consumers.')],
'React / Browser':[
('React render phase','The render phase calculates what the UI should look like for current props and state.','React invokes components and builds a new element tree; rendering should remain free of imperative side effects.','function App(){ return <Orders/> }','I separate render from commit because many React performance and side-effect bugs come from mixing those phases.'),
('React commit phase','The commit phase applies necessary changes to the host environment after reconciliation.','React updates DOM nodes and runs relevant layout/effect lifecycle work according to its scheduling model.','useEffect(()=>load(),[]);','I explain that a component can render without every render causing equivalent DOM work.'),
('Browser event loop','The browser coordinates JavaScript execution with tasks, microtasks, rendering and other browser work.','A task runs, microtasks drain, and the browser may render between turns; long synchronous work blocks input and painting.','queueMicrotask(()=>console.log("micro"));','I use the event loop to predict ordering and explain UI freezes rather than saying JavaScript is simply single-threaded.'),
('Promise microtasks','Promise callbacks run in the microtask queue after the current JavaScript stack completes.','Microtasks are drained before the browser proceeds to the next task, so excessive chains can delay rendering.','Promise.resolve().then(()=>console.log("micro"));','I use a concrete queue ordering example when explaining async JavaScript.'),
('React state batching','React can group state updates so multiple changes result in fewer renders.','Updates are queued and processed according to React’s scheduling rules; functional updates are important when deriving the next state from previous state.','setCount(c=>c+1); setCount(c=>c+1);','I use functional updates when several updates depend on prior state.'),
('Race conditions in data fetching','A fast-changing UI can have multiple requests in flight whose responses arrive out of order.','The latest request should control visible state; abort signals, request IDs or libraries can prevent stale responses from winning.','const c=new AbortController(); fetch(url,{signal:c.signal});','I treat cancellation and stale-result protection as part of correctness, not just optimization.')],
'Docker':[
('Image layers','Docker images are built from layered filesystem changes that can be reused between builds and images.','Each Dockerfile instruction can contribute a layer; cache reuse depends on instruction inputs and ordering.','COPY package.json ./\nRUN npm ci','I optimize layer boundaries around stable dependencies and frequently changing source.'),
('Container namespaces','Containers isolate processes using Linux kernel namespaces while sharing the host kernel.','PID, network, mount and other namespaces create isolated views; cgroups handle resource control separately.','docker run --pid=private app','I distinguish isolation from virtualization because containers do not include a separate kernel.'),
('Container networking','Container networking gives processes virtual interfaces and connectivity through Docker networks.','Bridge networks provide service connectivity; published ports connect host traffic to container ports.','docker run --network appnet api','I separate container-to-container ports from host-published ports when debugging connectivity.'),
('Multi-stage builds','Multi-stage builds separate build tooling from the final runtime image.','A builder stage compiles the application, and the runtime stage copies only required artifacts.','FROM eclipse-temurin:21 AS build\nFROM eclipse-temurin:21-jre','I use multi-stage builds to reduce attack surface and image size without sacrificing build reproducibility.'),
('Container PID 1','PID 1 inside a container has special signal and child-reaping responsibilities.','If the application is not an appropriate init process, signals may not propagate correctly and zombie processes can accumulate.','docker stop api','I verify graceful shutdown with the actual process tree rather than assuming SIGTERM reaches the app.'),
('Docker healthchecks','A healthcheck expresses whether a container is functioning according to an application-level probe.','The runtime executes the check and records health status, which orchestration systems can use as one input for decisions.','HEALTHCHECK CMD curl -f http://localhost:8080/actuator/health','I keep health checks cheap and meaningful; a process being alive is not necessarily being ready.')],
'Kubernetes':[
('API server and desired state','The Kubernetes API server is the front door for cluster state and API operations.','Clients write desired state; controllers observe resources and reconcile actual state toward that desired state.','kubectl apply -f deployment.yaml','I explain Kubernetes as an API plus reconciliation system rather than a collection of shell commands.'),
('Scheduler decision','The scheduler chooses a node for an unscheduled Pod based on constraints and available resources.','It filters infeasible nodes, scores candidates and binds the Pod to a selected node.','kubectl describe pod api-0','I diagnose Pending Pods by reading scheduler events and constraints before changing random node settings.'),
('Controller reconciliation','Controllers continuously compare desired and observed state and take actions to converge them.','A Deployment controller creates or updates ReplicaSets and Pods so the observed state approaches the declared replica and template state.','spec.replicas: 3','I describe reconciliation as an ongoing loop, which explains why deleting a managed Pod often causes it to return.'),
('Service endpoint selection','A Kubernetes Service provides a stable virtual destination for a changing set of Pods.','Selectors identify eligible Pods and endpoint data is updated as Pods become ready or unready.','selector:\n  app: api','I debug Service failures by checking selectors, endpoints and readiness before blaming networking.'),
('Probe semantics','Startup, readiness and liveness probes answer different questions about an application.','Startup protects slow initialization, readiness controls traffic eligibility, and liveness detects a stuck process that should be restarted.','readinessProbe:\n  httpGet: {path: /ready, port: 8080}','I never use liveness to represent dependency health when doing so could create restart storms.'),
('HPA control loop','Horizontal Pod Autoscaler changes desired replica count from observed metrics.','The controller compares current metric values with targets and adjusts replicas subject to min/max and timing constraints.','kubectl get hpa','I explain HPA as a feedback controller and include metric delay and downstream capacity in the design.')],
'CI/CD / GitHub Actions':[
('Workflow execution graph','A CI workflow is a graph of jobs and dependencies, not just a script.','Triggers create runs; jobs execute on runners, and needs/outputs determine ordering and data flow.','jobs: { test: { runs-on: ubuntu-latest } }','I design the graph around independent work, artifact boundaries and release gates.'),
('Artifact immutability','An immutable artifact is built once and promoted through environments without rebuilding.','The pipeline records a version or digest and later environments deploy that exact artifact.','image: app@sha256:...','I prefer immutable promotion because rebuilding between environments can change the thing being tested.'),
('OIDC workload identity','OIDC lets CI exchange a short-lived identity token for cloud credentials without storing long-lived keys.','The cloud provider validates claims such as repository, branch or environment before issuing temporary credentials.','permissions:\n  id-token: write','I constrain trust conditions tightly and grant the resulting role only the deployment permissions required.'),
('Concurrency control','CI concurrency prevents overlapping runs from racing over shared deployment targets.','Workflow groups can cancel obsolete runs or serialize operations so only one relevant deployment proceeds.','concurrency:\n  group: production','I use concurrency for deployment safety, while allowing independent validation work to run in parallel.'),
('Cache correctness','A CI cache speeds builds by reusing derived data, but a stale or overly broad cache can corrupt reproducibility.','Cache keys should include inputs that materially affect the derived dependency state, with restore keys used carefully.','key: maven-${{ hashFiles(\'**/pom.xml\') }}','I treat caches as performance hints, never as authoritative build inputs.'),
('Deployment verification','A deployment is incomplete until the pipeline proves the new version is healthy.','Verification can combine rollout status, health endpoints, metrics and smoke tests before promotion or completion.','kubectl rollout status deployment/api','I make verification an explicit stage so a successful command is not mistaken for a successful release.')],
'AWS / Cloud':[
('VPC routing','A VPC routes packets between subnets and connected networks according to route tables.','Each subnet is associated with a route table; local routes handle VPC traffic while gateways handle external destinations.','0.0.0.0/0 -> NAT Gateway','I debug cloud connectivity by tracing source subnet, route table, gateway and security controls in order.'),
('Security groups','Security groups act as stateful virtual firewalls attached to supported resources.','Inbound and outbound rules control allowed traffic, and return traffic is tracked as part of the connection state.','TCP 443 from ALB-SG','I prefer referencing security groups or narrow CIDRs instead of opening broad network access.'),
('IAM policy evaluation','IAM determines whether an action is allowed from applicable policies and explicit denies.','Identity/resource policies, conditions, permissions boundaries and other controls combine to determine the effective permission.','Action: s3:GetObject','I debug AccessDenied by identifying the principal, action, resource and every policy layer affecting the decision.'),
('Load balancer request flow','A load balancer accepts client traffic and forwards it to healthy targets.','Listeners apply protocol/port rules, target groups determine backend membership and health checks control eligibility.','client -> ALB:443 -> target:8080','I troubleshoot 502 by checking listener, target health, network path and application response in that order.'),
('RDS connection behavior','Managed databases still have finite connection, CPU, memory and I/O capacity.','Applications use pooled connections; excessive concurrency can exhaust the database even when application replicas appear healthy.','maximumPoolSize=20','I size application pools from database capacity and workload rather than per-Pod CPU alone.'),
('Cloud observability','Cloud observability combines infrastructure and application signals to explain system behavior.','Metrics reveal resource trends, logs provide event detail, and traces connect distributed request latency across services.','traceId=abc123','I correlate signals around one request or incident rather than reading dashboards in isolation.')],
}

lessons=[]
num=1
for track, items in tracks.items():
    for title,what,how,code,delivery in items:
        q1=f'What failure does {title.lower()} help you diagnose?'
        q2=f'What trade-off should you consider with {title.lower()}?'
        a1=f'It gives me a concrete boundary to inspect: I first verify the expected behavior, then compare it with runtime evidence such as logs, metrics, traces, generated SQL, events or configuration. I avoid changing multiple layers at once.'
        a2=f'The main trade-off is usually correctness or isolation versus cost: latency, memory, CPU, network calls, database work or operational complexity. I choose the simplest behavior that satisfies the system invariant.'
        traps=[f'Do not describe {title.lower()} as magic; name the runtime boundary that actually performs the work.', 'Do not optimize or change configuration before establishing the failure with evidence.']
        lessons.append(dict(id=f'iw-{num:03d}',level='L2' if num<=36 else 'L3',topic=track,title=title,what=what,how=how,code=code,delivery=delivery,followups=[q1,q2],followupAnswers=[a1,a2],traps=traps,realWorld=f'In production, this concept matters when the system crosses an abstraction boundary. Understanding the internal mechanism lets you predict behavior, interpret telemetry and choose a targeted fix instead of relying on trial and error.'))
        num+=1

labs_data=[
('Trace a request through the JVM','A Java API shows high latency but application CPU is not obviously saturated.','Trace one request from HTTP entry through controller, service, JPA and database, then identify where time is actually spent.',['Capture request trace.','Inspect thread/CPU evidence.','Check generated SQL and database timing.','Compare application and DB latency.','Explain the first slow boundary.'],['curl -v http://localhost:8080/orders/42','jstack <pid>','EXPLAIN (ANALYZE, BUFFERS) ...']),
('Explain a Spring proxy surprise','@Transactional appears on a method but rollback behavior is missing.','Prove whether the call crossed a Spring proxy and inspect transaction boundaries.',['Call the method through the injected bean.','Compare with self-invocation.','Inspect transaction logs.','Move the boundary if required.'],['this.inner();','transaction logs','@Transactional']),
('Diagnose an N+1 query','An endpoint returns 100 orders and emits hundreds of SQL statements.','Use SQL logging and request profiling to identify lazy association access and replace it with an intentional fetch plan.',['Count SQL statements.','Locate the loop triggering lazy loads.','Test fetch join/entity graph.','Compare response and query count.'],['Hibernate SQL logging','SELECT ... JOIN FETCH ...','EXPLAIN ANALYZE ...']),
('Read a PostgreSQL execution plan','A query became slow after data volume increased.','Compare estimated and actual rows and determine whether the chosen access path is still appropriate.',['Run EXPLAIN ANALYZE.','Inspect row estimates.','Inspect buffers and scan type.','Test a targeted index or query rewrite.'],['EXPLAIN (ANALYZE, BUFFERS) SELECT ...','CREATE INDEX ...']),
('Stop retry amplification','A dependency outage causes request volume to multiply across three services.','Map every retry layer, calculate worst-case amplification and reduce it with one bounded policy.',['List caller retries.','List SDK retries.','Calculate attempts.','Add backoff/jitter and idempotency.'],['attempts = r1 * r2 * r3','exponential backoff + jitter']),
('Recover a Kafka consumer group','Consumer lag grows while CPU is moderate.','Determine whether partition skew, downstream latency, rebalances or insufficient partition parallelism is limiting consumption.',['Inspect partition lag.','Compare per-partition processing time.','Check rebalance events.','Test controlled scaling.'],['kafka-consumer-groups --describe ...','records-lag-max']),
('Prove stale React data','A search box occasionally shows results for an older query.','Reproduce overlapping requests and make the latest request authoritative.',['Add artificial latency.','Log request IDs.','Observe out-of-order responses.','Abort or ignore stale responses.'],['AbortController','requestId === latestId']),
('Inspect Docker process behavior','A container takes too long to stop and leaves child processes behind.','Inspect PID 1 and signal propagation, then make shutdown behavior explicit.',['Inspect process tree.','Send SIGTERM.','Measure shutdown time.','Use a proper init/exec form.'],['docker exec <id> ps -ef','docker stop <id>']),
('Reconstruct Kubernetes reconciliation','A managed Pod is deleted and immediately returns.','Observe the controller chain from Deployment to ReplicaSet to Pod and explain why the desired state recreates it.',['Delete one Pod.','Watch ReplicaSet events.','Inspect Deployment desired replicas.','Explain reconciliation.'],['kubectl delete pod <pod>','kubectl get rs,pods -w','kubectl describe deployment api']),
('Debug a Kubernetes Pending Pod','A new replica never starts.','Use scheduler events and resource constraints to find the first unsatisfied scheduling condition.',['Describe the Pod.','Read Events.','Check node capacity.','Check affinity/taints/requests.'],['kubectl describe pod <pod>','kubectl get nodes','kubectl get events --sort-by=.lastTimestamp']),
('Follow a 502 through AWS','Users receive intermittent 502 responses through an ALB.','Trace listener, target health, network path and application behavior to find whether the failure is before or after the target.',['Check target health.','Check ALB access logs/metrics.','Check app logs.','Compare timeout and response behavior.'],['aws elbv2 describe-target-health ...','curl http://target:8080/health']),
('Diagnose connection-pool exhaustion','Requests queue waiting for database connections.','Correlate pool active/idle/waiting metrics with query latency and database capacity.',['Inspect Hikari metrics.','Inspect slow queries.','Check transaction duration.','Reduce unnecessary concurrency or fix leaks.'],['active / idle / pending','SELECT ... pg_stat_activity']),
('Verify immutable deployment','A production release behaves differently from staging despite the same source commit.','Prove whether the same built artifact/digest was promoted and eliminate environment-specific rebuilds.',['Record image digest.','Compare staging/prod digest.','Inspect pipeline build steps.','Promote exact artifact.'],['docker image inspect ...','kubectl get deploy -o yaml']),
('Exercise OIDC trust','A GitHub Actions workflow needs AWS access without stored access keys.','Configure short-lived identity and restrict trust to the intended repository/environment claims.',['Request OIDC token.','Configure trust condition.','Assume role.','Run least-privilege command.'],['permissions: id-token: write','aws sts get-caller-identity']),
('Observe one distributed request','A request is slow but each individual service dashboard looks healthy.','Use a trace ID to correlate gateway, service, Kafka and database timing for one request.',['Capture trace ID.','Find spans.','Compare service and DB durations.','Identify the longest critical-path span.'],['traceId=...','logs | grep traceId','trace spans']),
('Model a production failure budget','A release increases p99 latency slightly but errors remain low.','Decide using SLOs, tail latency and business impact rather than a single average metric.',['Check p95/p99.','Check SLO burn.','Check business metric.','Promote, pause or rollback.'],['p99 latency','error-budget burn']),
('Explain the system from first principles','An interviewer changes one requirement in a full-stack architecture.','Re-derive the architecture from the new constraint instead of defending the original component choices.',['State invariant.','Draw request/data path.','Identify consistency boundary.','Recalculate capacity.','Explain changed trade-offs.'],['requirements -> constraints -> design','trade-off -> consequence']),
('Build an internal-workings incident notebook','A production incident has scattered logs, metrics and commands but no coherent explanation.','Create a concise evidence chain from symptom to mechanism, mitigation, root cause and prevention.',['Capture timeline.','Attach evidence to each hypothesis.','Record mitigation.','Validate root cause.','Write prevention item.'],['symptom -> evidence -> hypothesis','mitigation -> root cause -> prevention'])
]
labs=[]
for i,(title,situation,goal,steps,commands) in enumerate(labs_data,1):
    labs.append(dict(id=f'iwlab-{i:03d}',level='L3',topic='System Behavior',title=title,situation=situation,goal=goal,steps=steps,commands=commands,delivery='I would first establish the failing boundary with evidence, then explain the internal mechanism that produces the symptom, apply the smallest safe correction and verify the result.',followups=['What evidence would prove your hypothesis?','What would you change if the first fix did not work?'],followupAnswers=['I would use a direct signal from the owning boundary: trace/span timing, SQL and execution plan, Kubernetes events, broker lag, process state, IAM decision or application logs. The evidence must distinguish competing explanations.','I would keep the hypothesis tree explicit, test the next highest-probability cause, and avoid stacking unrelated configuration changes. Each change should have a measurable expected effect.'],traps=['Do not jump straight to the most familiar technology as the root cause.','Do not declare recovery without verifying the original symptom and the relevant system invariant.']))

