def lesson_js(x):
    return f"lesson({js(x['id'])},{js(x['level'])},{js(x['topic'])},{js(x['title'])},{js(x['what'])},{js(x['how'])},{js(x['code'])},{js(x['delivery'])},{js(x['followups'])},{js(x['followupAnswers'])},{js(x['traps'])},{js(x['realWorld'])})"

p=root/'src/data/internalWorkingsLessons.js'
p.write_text('const lesson=(id,level,topic,title,what,how,code,delivery,followups,answers,traps,realWorld)=>({id,level,topic,title,what,how,code,delivery,followups,followupAnswers:answers,traps,realWorld});\n\nexport const internalWorkingsLessons=[\n'+',\n'.join(lesson_js(x) for x in lessons)+'\n];\n')

def lab_js(x):
    return f"lab({js(x['id'])},{js(x['level'])},{js(x['topic'])},{js(x['title'])},{js(x['situation'])},{js(x['goal'])},{js(x['steps'])},{js(x['commands'])},{js(x['delivery'])},{js(x['followups'])},{js(x['followupAnswers'])},{js(x['traps'])})"
(root/'src/data/internalWorkingsLabs.js').write_text('const lab=(id,level,topic,title,situation,goal,steps,commands,delivery,followups,answers,traps)=>({id,level,topic,title,situation,goal,steps,commands,delivery,followups,followupAnswers:answers,traps});\n\nexport const internalWorkingsLabs=[\n'+',\n'.join(lab_js(x) for x in labs)+'\n];\n')

# page
page='''import React,{useMemo,useState} from "react";\nimport {internalWorkingsLessons} from "../data/internalWorkingsLessons";\nimport {internalWorkingsLabs} from "../data/internalWorkingsLabs";\nfunction Card({item,open,onToggle,lab}){const followups=item.followups||[];return <article className="lesson-card scenario-card"><button className="lesson-head" onClick={onToggle}><span className="q-number">{item.id.split("-").pop()}</span><span className="lesson-title"><strong>{item.title}</strong><span className="meta"><i className="level">{item.level}</i><i>{lab?"Behavior Lab":item.topic}</i></span></span><span className="chevron">{open?"⌃":"⌄"}</span></button>{open&&<div className="lesson-body scenario-body"><div className="explain-section"><div className="section-kicker">WHAT IS IT?</div><p>{lab?item.situation:item.what}</p></div><div className="explain-section"><div className="section-kicker">INTERNAL MECHANISM</div><p>{lab?item.goal:item.how}</p></div><div className="explain-section"><div className="section-kicker">{lab?"LAB STEPS / COMMANDS":"RUNTIME EXAMPLE"}</div>{lab?<><ol className="mistake-list" style={{marginBottom:10}}>{item.steps.map((s,i)=><li key={i}>{s}</li>)}</ol><pre>{item.commands.join("\\n")}</pre></>:<pre>{item.code}</pre>}</div>{!lab&&<div className="explain-section"><div className="section-kicker">REAL-WORLD PERSPECTIVE</div><p>{item.realWorld}</p></div>}<div className="explain-section interview-script"><span className="script-label">INTERVIEW DELIVERY</span><p>{item.delivery}</p></div><div className="explain-section"><div className="section-kicker">EXPECTED FOLLOW-UPS</div><div className="followup-list">{followups.map((q,i)=><details className="followup-item" key={i}><summary>{q}</summary><div className="followup-answer"><strong>ANSWER</strong><p>{item.followupAnswers?.[i]}</p></div></details>)}</div></div><div className="explain-section mistake-section"><div className="section-kicker">COMMON TRAPS</div><ul className="mistake-list">{item.traps.map((t,i)=><li key={i}>{t}</li>)}</ul></div></div>}</article>}\nexport default function InternalWorkingsLearning(){const [tab,setTab]=useState("lessons"),[level,setLevel]=useState("all"),[query,setQuery]=useState(""),[open,setOpen]=useState({});const source=tab==="lessons"?internalWorkingsLessons:internalWorkingsLabs;const filtered=useMemo(()=>source.filter(x=>(level==="all"||x.level===level)&&JSON.stringify(x).toLowerCase().includes(query.toLowerCase())),[source,level,query]);const expandAll=()=>setOpen(Object.fromEntries(filtered.map(x=>[x.id,true])));return <section className="learning-page"><div className="learning-hero scenario-hero"><span className="pill">V22 · INTERNAL WORKINGS & SYSTEM BEHAVIOR</span><h2>Understand the mechanism.<br/><em>Predict the behavior.</em></h2><p>Go beneath the abstractions and learn what the runtime, framework, database, broker, browser, container, orchestrator and cloud actually do. Use internals to reason about performance, failure and production behavior.</p><div className="learning-flow"><span>Observe</span><b>→</b><span>Model</span><b>→</b><span>Trace</span><b>→</b><span>Predict</span><b>→</b><span>Debug</span><b>→</b><span>Explain</span></div></div><div className="learning-toolbar"><div className="search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search JVM, Spring, Hibernate, PostgreSQL, Kafka, React, Docker, Kubernetes, AWS..."/></div><div className="filters">{["all","L2","L3"].map(x=><button key={x} className={level===x?"filter active":"filter"} onClick={()=>setLevel(x)}>{x==="all"?"All levels":x}</button>)}</div></div><div className="subtopic-row"><button className={tab==="lessons"?"subtopic active":"subtopic"} onClick={()=>{setTab("lessons");setOpen({})}}>⚙ Internal Mechanisms <small>{internalWorkingsLessons.length}</small></button><button className={tab==="labs"?"subtopic active":"subtopic"} onClick={()=>{setTab("labs");setOpen({})}}>🔬 Behavior Labs <small>{internalWorkingsLabs.length}</small></button></div><div className="result-row"><span><b>{tab==="lessons"?"Internal Workings":"Behavior Labs"}</b> · {filtered.length} items</span><button onClick={expandAll}>Expand all</button><button onClick={()=>setOpen({})}>Collapse all</button></div><section className="lesson-list">{filtered.map(x=><Card key={x.id} item={x} lab={tab==="labs"} open={!!open[x.id]} onToggle={()=>setOpen(p=>({...p,[x.id]:!p[x.id]}))}/>)}</section></section>}\n'''
(root/'src/pages/InternalWorkingsLearning.jsx').write_text(page)

