        needle='''          <div className="side-label section-label practical-label">PRACTICAL ENGINEERING</div>'''
        block='''          <div className="side-label section-label advanced-label">INTERNAL WORKINGS</div>\n          <nav className="topic-nav">\n            <button className={view === "internal" ? "nav-item active" : "nav-item"} onClick={() => go("internal")}>\n              <span>⚙</span><label>Internal Workings</label><small>{internalWorkingsLessons.length + internalWorkingsLabs.length}</small>\n            </button>\n          </nav>\n\n'''
