        s=s.replace(': production ? `${capstoneLessons.length + capstoneLabs.length} CAPSTONE ITEMS` : deepDive ? `${deepDiveLessons.length + deepDiveLabs.length} DEEP-DIVE ITEMS` : `${questions.length} QUESTIONS`', ': production ? `${capstoneLessons.length + capstoneLabs.length} CAPSTONE ITEMS` : deepDive ? `${deepDiveLessons.length + deepDiveLabs.length} DEEP-DIVE ITEMS` : internal ? `${internalWorkingsLessons.length + internalWorkingsLabs.length} INTERNAL ITEMS` : `${questions.length} QUESTIONS`')
        s=s.replace(': production ? "production@engineering:~" : deepDive ? "architecture@deep-learning:~" : "backend@interview:~"', ': production ? "production@engineering:~" : deepDive ? "architecture@deep-learning:~" : internal ? "runtime@system-behavior:~" : "backend@interview:~"')
